from test.support.numbers import VALID_UNDERSCORE_LITERALS, INVALID_UNDERSCORE_LITERALS

def _t():
    for lit in VALID_UNDERSCORE_LITERALS:
        if any((ch in lit for ch in '.eEjJ')):
            continue
        assert int(lit, 0) == eval(lit), ('assertEqual', int(lit, 0), eval(lit))
        assert int(lit, 0) == int(lit.replace('_', ''), 0), ('assertEqual', int(lit, 0), int(lit.replace('_', ''), 0))
    for lit in INVALID_UNDERSCORE_LITERALS:
        if any((ch in lit for ch in '.eEjJ')):
            continue
        try:
            int(*(lit, 0))
        except ValueError:
            pass
    assert int('1_00', 3) == 9, ('assertEqual', int('1_00', 3), 9)
    assert int('0_100') == 100, ('assertEqual', int('0_100'), 100)
    assert int(b'1_00') == 100, ('assertEqual', int(b'1_00'), 100)
    try:
        int(*('_100',))
    except ValueError:
        pass
    try:
        int(*('+_100',))
    except ValueError:
        pass
    try:
        int(*('1__00',))
    except ValueError:
        pass
    try:
        int(*('100_',))
    except ValueError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

