def _t():
    """Testing the supported limits of the int() base parameter."""
    assert int('0', 5) == 0, ('assertEqual', int('0', 5), 0)
    try:
        int('0', 1)
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        int('0', 37)
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        int('0', -909)
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        int('0', base=0 - 2 ** 234)
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        int('0', base=2 ** 234)
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    for base in range(2, 37):
        assert int('0', base=base) == 0, ('assertEqual', int('0', base=base), 0)
